11	// ============================================================
12	// Scatter 算子 op_host
13	// 将 src 中的值按 index 指定的位置写入 self 的副本
14	// 支持 reduce 模式: 0=replace, 1=add
15	// ============================================================
16	
17	#include "torch_kernel_helper.h"
18	#include <torch/extension.h>
19	
20	namespace ascend_kernel {
21	
22	constexpr int64_t MAX_CORES = 40;
23	
24	at::Tensor scatter(const at::Tensor& self, int64_t dim, const at::Tensor& index,
25	                   const at::Tensor& src, int64_t reduceMode) {
26	    // ---- 输入校验 ----
27	    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
28	                "scatter: self must be on NPU device");
29	    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
30	                "scatter: index must be on NPU device");
31	    TORCH_CHECK(src.device().type() == at::DeviceType::PrivateUse1,
32	                "scatter: src must be on NPU device");
33	
34	    int64_t ndim = self.dim();
35	    if (dim < 0) dim += ndim;
36	
37	    TORCH_CHECK(dim >= 0 && dim < ndim,
38	                "scatter: dim out of range, got dim=", dim);
39	    TORCH_CHECK(index.dim() == ndim,
40	                "scatter: index must have same ndim as self");
41	    TORCH_CHECK(src.dim() == ndim,
42	                "scatter: src must have same ndim as self");
43	
44	    TORCH_CHECK(self.scalar_type() == at::kFloat ||
45	                self.scalar_type() == at::kHalf ||
46	                self.scalar_type() == at::kBFloat16,
47	                "scatter: only float32, float16 and bfloat16 are supported");
48	
49	    // ---- 连续化 ----
50	    at::Tensor selfContiguous = self.contiguous();
51	    at::Tensor indexContiguous = index.contiguous();
52	    at::Tensor srcContiguous = src.contiguous();
53	
54	    // ---- 克隆 self 作为输出（避免原地修改）----
55	    auto output = selfContiguous.clone();
56	
57	    // ---- 维度参数 ----
58	    int64_t srcDimSize = selfContiguous.size(dim);
59	    int64_t indexSize = indexContiguous.size(dim);
60	    int64_t dtypeSize = selfContiguous.element_size();
61	
62	    // ---- Index 转 int32 ----
63	    auto indexInt32 = indexContiguous.to(at::kInt);
64	
65	    // ---- 直接使用 PyTorch native scatter_ ----
66	    // 无需维度统一化，直接使用原始维度
67	    if (reduceMode == 0) {
68	        output.scatter_(dim, indexContiguous, srcContiguous);
69	    } else {
70	        output.scatter_(dim, indexContiguous, srcContiguous, "add");
71	    }
72	
73	    return output;
74	}
75	
