11	// ============================================================
12	// Scatter 算子 op_kernel
13	// 将 src 中的值按 index 指定的位置写入 self 的副本
14	// 支持 reduce 模式: 0=replace, 1=add
15	// 分核模式 B: 每核独占一行，避免写竞争
16	// ============================================================
17	
18	#include "kernel_operator.h"
19	
20	using namespace AscendC;
21	
22	constexpr int64_t UB_CAPACITY = 192 * 1024;
23	constexpr int64_t MAX_CORES = 40;
24	
25	template <typename T>
26	class ScatterKernel {
27	public:
28	    __aicore__ inline ScatterKernel() {}
29	
30	    __aicore__ inline void Init(GM_ADDR self, GM_ADDR index, GM_ADDR src,
31	                                 int64_t totalRows, int64_t srcDimSize,
32	                                 int64_t indexSize, int64_t reduceMode);
33	    __aicore__ inline void Process();
34	
35	private:
36	    __aicore__ inline void ProcessRow(int64_t row);
37	    __aicore__ inline void ProcessRowAdd(int64_t row);
38	
39	    TPipe pipe;
40	
41	    // Buffers
42	    TBuf<TPosition::VECIN> selfBuf;
43	    TBuf<TPosition::VECIN> idxBuf;
44	    TBuf<TPosition::VECIN> srcBuf;
45	
46	    GlobalTensor<T> selfGm;
47	    GlobalTensor<int32_t> indexGm;
48	    GlobalTensor<T> srcGm;
49	
50	    int64_t totalRows_ = 0;
51	    int64_t srcDimSize_ = 0;
52	    int64_t indexSize_ = 0;
53	    int64_t reduceMode_ = 0;
54	    int64_t selfRowBytes_ = 0;
55	    int64_t idxBytes_ = 0;
56	    int64_t srcBytes_ = 0;
57	};
58	
59	template <typename T>
60	__aicore__ inline void ScatterKernel<T>::Init(GM_ADDR self, GM_ADDR index, GM_ADDR src,
61	                                               int64_t totalRows, int64_t srcDimSize,
62	                                               int64_t indexSize, int64_t reduceMode) {
63	    totalRows_ = totalRows;
64	    srcDimSize_ = srcDimSize;
65	    indexSize_ = indexSize;
66	    reduceMode_ = reduceMode;
67	
68	    selfGm.SetGlobalBuffer((__gm__ T *)self, totalRows * srcDimSize);
69	    indexGm.SetGlobalBuffer((__gm__ int32_t *)index, totalRows * indexSize);
70	    srcGm.SetGlobalBuffer((__gm__ T *)src, totalRows * indexSize);
71	
72	    // 32字节对齐
73	    selfRowBytes_ = (srcDimSize * sizeof(T) + 31) / 32 * 32;
74	    idxBytes_ = (sizeof(int32_t) + 31) / 32 * 32;
75	    srcBytes_ = (sizeof(T) + 31) / 32 * 32;
76	
77	    // 分配buffer: self行 + 单个index + 单个src
78	    pipe.InitBuffer(selfBuf, selfRowBytes_);
79	    pipe.InitBuffer(idxBuf, idxBytes_);
80	    pipe.InitBuffer(srcBuf, srcBytes_);
81	}
82	
83	template <typename T>
84	__aicore__ inline void ScatterKernel<T>::ProcessRow(int64_t row) {
85	    // 1. 读入self的一整行到UB
86	    LocalTensor<T> selfLocal = selfBuf.Get<T>();
87	    DataCopyExtParams selfCopyParams;
88	    selfCopyParams.blockCount = 1;
89	    selfCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
90	    selfCopyParams.srcStride = 0;
91	    selfCopyParams.dstStride = 0;
92	    DataCopyPadExtParams<T> selfPadParams;
93	    selfPadParams.isPad = false;
94	    DataCopyPad(selfLocal, selfGm[row * srcDimSize_], selfCopyParams, selfPadParams);
95	    PipeBarrier<PIPE_ALL>();
96	
97	    // 2. 逐元素scatter
98	    for (int64_t k = 0; k < indexSize_; ++k) {
99	        // 加载index[k]
100	        LocalTensor<int32_t> idxLocal = idxBuf.Get<int32_t>();
101	        DataCopyExtParams idxCopyParams;
102	        idxCopyParams.blockCount = 1;
103	        idxCopyParams.blockLen = static_cast<uint32_t>(sizeof(int32_t));
104	        idxCopyParams.srcStride = 0;
105	        idxCopyParams.dstStride = 0;
106	        DataCopyPad(idxLocal, indexGm[row * indexSize_ + k], idxCopyParams);
107	        PipeBarrier<PIPE_ALL>();
108	        int32_t idx = idxLocal.GetValue(0);
109	
110	        // 加载src[k]
111	        LocalTensor<T> srcLocal = srcBuf.Get<T>();
112	        DataCopyExtParams srcCopyParams;
113	        srcCopyParams.blockCount = 1;
114	        srcCopyParams.blockLen = static_cast<uint32_t>(sizeof(T));
115	        srcCopyParams.srcStride = 0;
116	        srcCopyParams.dstStride = 0;
117	        DataCopyPad(srcLocal, srcGm[row * indexSize_ + k], srcCopyParams);
118	        PipeBarrier<PIPE_ALL>();
119	
120	        // scatter写入selfLocal
121	        if (reduceMode_ == 0) {
122	            // replace模式
123	            selfLocal.SetValue(idx, srcLocal.GetValue(0));
124	        } else {
125	            // add模式
126	            if constexpr (sizeof(T) == sizeof(float)) {
127	                T oldVal = selfLocal.GetValue(idx);
128	                T newVal = oldVal + srcLocal.GetValue(0);
129	                selfLocal.SetValue(idx, newVal);
130	            } else {
131	                // FP16/BF16: 升精度到FP32计算
132	                float oldValFp32 = static_cast<float>(selfLocal.GetValue(idx));
133	                float srcValFp32 = static_cast<float>(srcLocal.GetValue(0));
134	                float newValFp32 = oldValFp32 + srcValFp32;
135	                selfLocal.SetValue(idx, static_cast<T>(newValFp32));
136	            }
137	        }
138	    }
139	
140	    // 3. 写回self行
141	    DataCopyExtParams outCopyParams;
142	    outCopyParams.blockCount = 1;
143	    outCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
144	    outCopyParams.srcStride = 0;
145	    outCopyParams.dstStride = 0;
146	    DataCopyPad(selfGm[row * srcDimSize_], selfLocal, outCopyParams);
147	    PipeBarrier<PIPE_ALL>();
148	}
149	
150	template <typename T>
151	__aicore__ inline void ScatterKernel<T>::Process() {
152	    int64_t blockIdx_ = GetBlockIdx();
153	    if (blockIdx_ >= totalRows_) return;
154	
155	    int64_t row = blockIdx_;
156	    ProcessRow(row);
157	}
158	
159	// =========================== Kernel 入口 ============================
160	
161	extern "C" __global__ __aicore__ void scatter(GM_ADDR self, GM_ADDR index, GM_ADDR src,
162	                                                 int64_t totalRows, int64_t srcDimSize,
163	                                                 int64_t indexSize, int64_t reduceMode,
164	                                                 int64_t dtypeSize) {
165	    if (dtypeSize == 4) {
166	        ScatterKernel<float> op;
167	        op.Init(self, index, src, totalRows, srcDimSize, indexSize, reduceMode);
168	        op.Process();
169	    } else if (dtypeSize == 2) {
170	        ScatterKernel<half> op;
171	        op.Init(self, index, src, totalRows, srcDimSize, indexSize, reduceMode);
172	        op.Process();
173	    }
174	}
