// ============================================================
// ScatterList 算子 op_kernel
// 将 updates 中沿 axis 轴 [0, length) 区间的连续数据块拷贝到
// varRef 中沿 axis 轴 [start, start+length) 区间
// 支持 reduce 模式: 0=replace(直接拷贝), 1=add(累加)
// 分核策略: 按 outerRow 分发，每核处理 ceil(outerRows/blockDim) 行
// 搬运策略: 将 dataLen=length*innerSize 连续元素经 UB 中转拷贝
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

template <typename T>
class ScatterListKernel {
public:
    __aicore__ inline ScatterListKernel() {}

    __aicore__ inline void Init(GM_ADDR dst, GM_ADDR src,
                                 int64_t outerRows, int64_t srcDimSize,
                                 int64_t innerSize, int64_t start,
                                 int64_t length, int64_t dataLen,
                                 int64_t rowsPerCore, int64_t tileLength,
                                 int64_t dtypeSize, int64_t reduceMode);
    __aicore__ inline void Process();

private:
    __aicore__ inline void ProcessRowReplace(int64_t row);
    __aicore__ inline void ProcessRowAdd(int64_t row);

    TPipe pipe;

    // replace 模式: 单 buffer 用于 src→UB→dst 中转
    TBuf<TPosition::VECIN> dataBuf;

    // add 模式额外 buffer
    TBuf<TPosition::VECIN>  dstReadBuf;   // 读目标数据
    TBuf<TPosition::VECCALC> calcBuf;      // FP32 计算缓冲 (FP16 add 时使用)

    GlobalTensor<T> dstGm;
    GlobalTensor<T> srcGm;

    int64_t outerRows_ = 0;
    int64_t srcDimSize_ = 0;
    int64_t innerSize_ = 0;
    int64_t start_ = 0;
    int64_t length_ = 0;
    int64_t dataLen_ = 0;
    int64_t rowsPerCore_ = 0;
    int64_t tileLength_ = 0;
    int64_t dtypeSize_ = 0;
    int64_t reduceMode_ = 0;
    int64_t tileNum_ = 0;
};

template <typename T>
__aicore__ inline void ScatterListKernel<T>::Init(
    GM_ADDR dst, GM_ADDR src,
    int64_t outerRows, int64_t srcDimSize,
    int64_t innerSize, int64_t start,
    int64_t length, int64_t dataLen,
    int64_t rowsPerCore, int64_t tileLength,
    int64_t dtypeSize, int64_t reduceMode) {

    outerRows_ = outerRows;
    srcDimSize_ = srcDimSize;
    innerSize_ = innerSize;
    start_ = start;
    length_ = length;
    dataLen_ = dataLen;
    rowsPerCore_ = rowsPerCore;
    tileLength_ = tileLength;
    dtypeSize_ = dtypeSize;
    reduceMode_ = reduceMode;

    int64_t totalDstElems = outerRows * srcDimSize * innerSize;
    int64_t totalSrcElems = outerRows * srcDimSize * innerSize;
    dstGm.SetGlobalBuffer((__gm__ T*)dst, totalDstElems);
    srcGm.SetGlobalBuffer((__gm__ T*)src, totalSrcElems);

    tileNum_ = (dataLen_ + tileLength_ - 1) / tileLength_;

    if (reduceMode_ == 0) {
        // replace 模式: 单 buffer 做中转 (GM(src)→UB→GM(dst))
        int64_t bufBytes = (tileLength_ * sizeof(T) + 31) / 32 * 32;
        pipe.InitBuffer(dataBuf, bufBytes);
    } else {
        // add 模式: dst_read_buf + src读需要通过dataBuf + fp32计算buf
        int64_t bufBytes = (tileLength_ * sizeof(T) + 31) / 32 * 32;
        pipe.InitBuffer(dataBuf, bufBytes);        // 用于 src 加载
        pipe.InitBuffer(dstReadBuf, bufBytes);      // 用于 dst 加载
        if (sizeof(T) == sizeof(half)) {
            // FP16 add: 需要 FP32 中间缓冲
            int64_t fp32Bytes = (tileLength_ * sizeof(float) + 31) / 32 * 32;
            pipe.InitBuffer(calcBuf, fp32Bytes * 2); // srcFp32 + dstFp32
        }
    }
}

template <typename T>
__aicore__ inline void ScatterListKernel<T>::ProcessRowReplace(int64_t row) {
    int64_t rowBase = row * srcDimSize_ * innerSize_;
    int64_t srcBase = rowBase;                          // src: 从 0 开始沿 axis
    int64_t dstBase = rowBase + start_ * innerSize_;    // dst: 从 start 开始沿 axis

    LocalTensor<T> bufLocal = dataBuf.Get<T>();

    for (int64_t t = 0; t < tileNum_; ++t) {
        int64_t offset = t * tileLength_;
        int64_t curLen = (t == tileNum_ - 1) ? (dataLen_ - offset) : tileLength_;

        // CopyIn: GM(src) → UB
        DataCopyExtParams copyInParams;
        copyInParams.blockCount = 1;
        copyInParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
        copyInParams.srcStride = 0;
        copyInParams.dstStride = 0;
        DataCopyPad(bufLocal, srcGm[srcBase + offset], copyInParams);
        PipeBarrier<PIPE_ALL>();

        // CopyOut: UB → GM(dst)
        DataCopyExtParams copyOutParams;
        copyOutParams.blockCount = 1;
        copyOutParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
        copyOutParams.srcStride = 0;
        copyOutParams.dstStride = 0;
        DataCopyPad(dstGm[dstBase + offset], bufLocal, copyOutParams);
        PipeBarrier<PIPE_ALL>();
    }
}

template <typename T>
__aicore__ inline void ScatterListKernel<T>::ProcessRowAdd(int64_t row) {
    int64_t rowBase = row * srcDimSize_ * innerSize_;
    int64_t srcBase = rowBase;
    int64_t dstBase = rowBase + start_ * innerSize_;

    for (int64_t t = 0; t < tileNum_; ++t) {
        int64_t offset = t * tileLength_;
        int64_t curLen = (t == tileNum_ - 1) ? (dataLen_ - offset) : tileLength_;

        // 1. 加载 dst[offset:offset+curLen] → UB
        LocalTensor<T> dstLocal = dstReadBuf.Get<T>();
        DataCopyExtParams dstCopyParams;
        dstCopyParams.blockCount = 1;
        dstCopyParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
        dstCopyParams.srcStride = 0;
        dstCopyParams.dstStride = 0;
        DataCopyPad(dstLocal, dstGm[dstBase + offset], dstCopyParams);
        PipeBarrier<PIPE_ALL>();

        // 2. 加载 src[offset:offset+curLen] → UB
        LocalTensor<T> srcLocal = dataBuf.Get<T>();
        DataCopyExtParams srcCopyParams;
        srcCopyParams.blockCount = 1;
        srcCopyParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
        srcCopyParams.srcStride = 0;
        srcCopyParams.dstStride = 0;
        DataCopyPad(srcLocal, srcGm[srcBase + offset], srcCopyParams);
        PipeBarrier<PIPE_ALL>();

        // 3. Compute: dst += src
        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32: 直接 Add
            Add(dstLocal, dstLocal, srcLocal, curLen);
        } else {
            // FP16/BF16: 升精度到 FP32 → Add → 降精度到 FP16
            LocalTensor<float> calcFp32 = calcBuf.Get<float>();
            LocalTensor<float> srcFp32 = calcFp32;
            LocalTensor<float> dstFp32 = calcFp32[tileLength_]; // 第二个 FP32 buffer

            Cast(dstFp32, dstLocal, RoundMode::CAST_NONE, curLen);
            Cast(srcFp32, srcLocal, RoundMode::CAST_NONE, curLen);
            Add(dstFp32, dstFp32, srcFp32, curLen);
            Cast(dstLocal, dstFp32, RoundMode::CAST_ROUND, curLen);
        }
        PipeBarrier<PIPE_ALL>();

        // 4. 写回 dst[offset:offset+curLen]
        DataCopyExtParams outParams;
        outParams.blockCount = 1;
        outParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
        outParams.srcStride = 0;
        outParams.dstStride = 0;
        DataCopyPad(dstGm[dstBase + offset], dstLocal, outParams);
        PipeBarrier<PIPE_ALL>();
    }
}

template <typename T>
__aicore__ inline void ScatterListKernel<T>::Process() {
    int64_t blockIdx = GetBlockIdx();
    int64_t blockDim = static_cast<int64_t>(GetBlockDim());
    if (blockIdx >= blockDim) return;

    int64_t rowStart = blockIdx * rowsPerCore_;
    int64_t rowEnd = rowStart + rowsPerCore_;
    if (rowEnd > outerRows_) rowEnd = outerRows_;
    if (rowStart >= outerRows_) return;

    for (int64_t r = rowStart; r < rowEnd; ++r) {
        if (reduceMode_ == 0) {
            ProcessRowReplace(r);
        } else {
            ProcessRowAdd(r);
        }
    }
}

// =========================== Kernel 入口 ============================

