// ============================================================
// ScatterList 算子 op_host
// 处理单对 (ref, src) 的沿 axis 连续块 scatter 操作
// 策略: 按 outerRow 分发到各核，UB 级按 tileLength 分块搬运
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_scatter_list.h"
#include <torch/extension.h>

namespace ascend_kernel {

constexpr int64_t CORE_NUM_MAX = 40;

at::Tensor scatter_list(
    const at::Tensor& ref,
    const at::Tensor& src,
    int64_t start,
    int64_t length,
    int64_t axis,
    int64_t reduceMode) {

    // ---- 输入校验 ----
    TORCH_CHECK(ref.device().type() == at::DeviceType::PrivateUse1,
                "scatter_list: ref must be on NPU device");
    TORCH_CHECK(src.device().type() == at::DeviceType::PrivateUse1,
                "scatter_list: src must be on NPU device");

    int64_t ndim = ref.dim();
    if (axis < 0) axis += ndim;

    TORCH_CHECK(axis >= 0 && axis < ndim,
                "scatter_list: axis out of range, got axis=", axis);
    TORCH_CHECK(length >= 0,
                "scatter_list: length must be >= 0, got length=", length);
    TORCH_CHECK(start >= 0 && start + length <= ref.size(axis),
                "scatter_list: start+length out of range for ref axis");

    TORCH_CHECK(ref.scalar_type() == at::kFloat ||
                ref.scalar_type() == at::kHalf,
                "scatter_list: only float32 and float16 are supported");

    // ---- 连续化 ----
    at::Tensor refContiguous = ref.contiguous();
    at::Tensor srcContiguous = src.contiguous();

    // ---- 克隆 ref 作为输出 ----
    auto output = refContiguous.clone();

    // ---- 维度参数 ----
    int64_t srcDimSize = refContiguous.size(axis);

    // innerSize: axis 之后各维度之积
    int64_t innerSize = 1;
    for (int64_t d = axis + 1; d < ndim; ++d) {
        innerSize *= refContiguous.size(d);
    }

    // outerRows: axis 之前各维度之积
    int64_t outerRows = 1;
    for (int64_t d = 0; d < axis; ++d) {
        outerRows *= refContiguous.size(d);
    }

    int64_t dataLen = length * innerSize;
    int64_t dtypeSize = refContiguous.element_size();

    // ---- Tiling 计算 ----
    // Block 级: 按 outerRow 分发
    int64_t blockDim = outerRows;
    if (blockDim > CORE_NUM_MAX) blockDim = CORE_NUM_MAX;
    if (blockDim < 1) blockDim = 1;

    int64_t rowsPerCore = (outerRows + blockDim - 1) / blockDim;

    // UB 级: 计算 tileLength
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint64_t ubSize = 0;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int64_t bufferCoefficient;
    if (reduceMode == 0) {
        // replace 模式: 单 buffer * 1 (无 double-buffer, 顺序加载-存储)
        bufferCoefficient = dtypeSize;
    } else if (dtypeSize == 4) {
        // add/FP32: srcBuf + dstBuf = 2 * 4 = 8
        bufferCoefficient = 8;
    } else {
        // add/FP16: srcBuf(2) + dstBuf(2) + fp32Buf(4*2) = 12
        bufferCoefficient = 12;
    }

    int64_t maxTileElements = static_cast<int64_t>(ubSize) * 3 / 4 / bufferCoefficient;
    if (maxTileElements < 1) maxTileElements = 1;

    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < alignElements) tileLength = alignElements;

    // 限制 tileLength 不超过 dataLen
    if (tileLength > dataLen) tileLength = dataLen;

    // ---- Kernel Launch ----
    // EXEC_KERNEL_CMD 要求所有参数为左值
    int64_t outerRowsVal = outerRows;
    int64_t srcDimSizeVal = srcDimSize;
    int64_t innerSizeVal = innerSize;
    int64_t startVal = start;
    int64_t lengthVal = length;
    int64_t dataLenVal = dataLen;
    int64_t rowsPerCoreVal = rowsPerCore;
    int64_t tileLengthVal = tileLength;
    int64_t dtypeSizeVal = dtypeSize;
    int64_t reduceModeVal = reduceMode;
    int32_t blockDimVal = static_cast<int32_t>(blockDim);

    EXEC_KERNEL_CMD(scatter_list, blockDimVal,
                    output, srcContiguous,
                    outerRowsVal, srcDimSizeVal, innerSizeVal,
                    startVal, lengthVal, dataLenVal,
                    rowsPerCoreVal, tileLengthVal,
                    dtypeSizeVal, reduceModeVal);

    return output;
}

}  // namespace ascend_kernel
