12	class QuantScatterKernel {
13	public:
14	    __aicore__ inline QuantScatterKernel() {}
15	    __aicore__ inline void Init(
16	            GM_ADDR output, GM_ADDR indices, GM_ADDR quantized,
17	            int64_t rowStart, int64_t rowCount, int64_t innerDim,
18	            int64_t tileLength, int64_t outStride0, int64_t outStride1,
19	            int64_t qStride0) {
20	        rowStart_ = rowStart; rowCount_ = rowCount; innerDim_ = innerDim;
21	        tileLength_ = tileLength; outStride0_ = outStride0; outStride1_ = outStride1;
22	        qStride0_ = qStride0;
23	        outGm_.SetGlobalBuffer((__gm__ int8_t*)output);
24	        idxGm_.SetGlobalBuffer((__gm__ int32_t*)indices);
25	        qGm_.SetGlobalBuffer((__gm__ int8_t*)quantized);
26	        pipe_.InitBuffer(buf_, tileLength_ * sizeof(int8_t));
27	    }
28	
29	    __aicore__ inline void Process() {
30	        int64_t bid = GetBlockIdx();
31	        if (bid >= rowCount_) return;
32	        int64_t row = rowStart_ + bid;
33	        int64_t iv = static_cast<int64_t>(idxGm_.GetValue(row));
34	
35	        int64_t tn = (innerDim_ + tileLength_ - 1) / tileLength_;
36	        int64_t tt = innerDim_ - (tn - 1) * tileLength_;
37	
38	        for (int64_t t = 0; t < tn; ++t) {
39	            int64_t cl = (t == tn - 1) ? tt : tileLength_;
40	            int64_t to = t * tileLength_;
41	
42	            LocalTensor<int8_t> local = buf_.Get<int8_t>();
43	
44	            // Load quantized tile GM→UB
45	            {
46	                DataCopyExtParams cp;
47	                cp.blockCount = 1;
48	                cp.blockLen = static_cast<uint32_t>(cl * sizeof(int8_t));
49	                cp.srcStride = 0; cp.dstStride = 0;
50	                DataCopyPadExtParams<int8_t> pp; pp.isPad = false;
51	                DataCopyPad(local, qGm_[row * qStride0_ + to], cp, pp);
52	            }
53	            PipeBarrier<PIPE_ALL>();
54	
55	            // Scatter write UB→GM
56	            {
57	                DataCopyExtParams cp;
58	                cp.blockCount = 1;
59	                cp.blockLen = static_cast<uint32_t>(cl * sizeof(int8_t));
60	                cp.srcStride = 0; cp.dstStride = 0;
61	                int64_t oo = row * outStride0_ + iv * outStride1_ + to;
62	                DataCopyPad(outGm_[oo], local, cp);
