            DataCopyExtParams cp;
            cp.blockCount = 1;
            cp.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
            cp.srcStride = 0;
            cp.dstStride = 0;
            DataCopyPadExtParams<T> pp;
            pp.isPad = false;
            DataCopyPad(dstLocal, dstGm[static_cast<uint64_t>(dstOff + to)], cp, pp);
        }
        PipeBarrier<PIPE_ALL>();

        // 2. Load src -> UB
