template <typename T>
__aicore__ inline void ScatterListKernel<T>::ProcessRowAdd(int64_t row) {
    int64_t rowBase = row * srcDimSize_ * innerSize_;
    int64_t dstOff = rowBase + start_ * innerSize_;
    int64_t srcOff = rowBase;

    int64_t tn = (dataLen_ + tileLength_ - 1) / tileLength_;
    int64_t tt = dataLen_ - (tn - 1) * tileLength_;

    if constexpr (sizeof(T) == sizeof(float)) {
        // FP32 add: direct vector add
        for (int64_t t = 0; t < tn; ++t) {
            int64_t curLen = (t == tn - 1) ? tt : tileLength_;
            int64_t to = t * tileLength_;

            // 1. Load dst -> UB
            LocalTensor<float> dstLocal = dstReadBuf.Get<float>();
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(float));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPadExtParams<float> pp;
                pp.isPad = false;
                DataCopyPad(dstLocal, dstGm[static_cast<uint64_t>(dstOff + to)], cp, pp);
            }
            PipeBarrier<PIPE_ALL>();

            // 2. Load src -> UB
            LocalTensor<float> srcLocal = dataBuf.Get<float>();
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(float));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPadExtParams<float> pp;
                pp.isPad = false;
                DataCopyPad(srcLocal, srcGm[static_cast<uint64_t>(srcOff + to)], cp, pp);
            }
            PipeBarrier<PIPE_ALL>();

            // 3. Compute: dstLocal += srcLocal
            Add(dstLocal, dstLocal, srcLocal, curLen);
            PipeBarrier<PIPE_ALL>();

            // 4. Write back dst -> GM
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(float));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPad(dstGm[static_cast<uint64_t>(dstOff + to)], dstLocal, cp);
            }
            PipeBarrier<PIPE_ALL>();
        }
    } else {
        // FP16 add: Cast -> FP32 -> Add -> Cast back
        for (int64_t t = 0; t < tn; ++t) {
            int64_t curLen = (t == tn - 1) ? tt : tileLength_;
            int64_t to = t * tileLength_;

            // 1. Load dst -> UB (as FP16)
            LocalTensor<half> dstHalf = dstReadBuf.Get<half>();
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPadExtParams<half> pp;
                pp.isPad = false;
                DataCopyPad(dstHalf, dstGm[static_cast<uint64_t>(dstOff + to)], cp, pp);
            }
            PipeBarrier<PIPE_ALL>();

            // 2. Load src -> UB (as FP16)
            LocalTensor<half> srcHalf = dataBuf.Get<half>();
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPadExtParams<half> pp;
                pp.isPad = false;
                DataCopyPad(srcHalf, srcGm[static_cast<uint64_t>(srcOff + to)], cp, pp);
            }
            PipeBarrier<PIPE_ALL>();

            // 3. Cast both to FP32, Add, Cast back
            LocalTensor<float> work = calcBuf.Get<float>();
            Cast(work, dstHalf, RoundMode::CAST_NONE, curLen);
