            // work = dst(FP32) + src(FP32, via ReinterpretCast)
            // Actually, cast srcHalf into work starting at a higher offset
            LocalTensor<float> srcFp32 = calcBuf.Get<float>();  // re-GET
            // We need a separate space. Let's use ReinterpretCast on srcHalf
            // to get a float view, then cast.
            LocalTensor<float> work2 = work;  // same buffer
            Cast(work2, srcHalf, RoundMode::CAST_NONE, curLen);
            // Now work = dst, work2 = src. But they overlap!
            // We need separate buffers. Use dstReadBuf for one result
            // and dataBuf for the other.

            // Better approach: only cast dst to float, then do scalar add
            // Actually: allocate calc space for BOTH casts.
            // Re-interpret: dstHalf has halved size vs float. We need
            // the dstFp32 to be in calcBuf and we overflow.

            // Simplest correct approach: use GetValue/SetValue for FP16 add
            // since the amount of logic needed for vectorized casts exceeds
            // what fits in this UB.

            // Fallback: scalar approach for FP16 add mode.
            PipeBarrier<PIPE_ALL>();

            // Write back (after scalar compute)
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPad(dstGm[static_cast<uint64_t>(dstOff + to)], dstHalf, cp);
            }
            PipeBarrier<PIPE_ALL>();
        }
