                DataCopyPad(srcLocal, srcGm[static_cast<uint64_t>(srcOff + to)], cp, pp);
            }
            PipeBarrier<PIPE_ALL>();

            // Compute: dstLocal += srcLocal
            Add(dstLocal, dstLocal, srcLocal, curLen);
            PipeBarrier<PIPE_ALL>();

            // Write back
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(float));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPad(dstGm[static_cast<uint64_t>(dstOff + to)], dstLocal, cp);
            }
            PipeBarrier<PIPE_ALL>();
        } else {
            // FP16 add path: load half, cast to float, add, cast back
            int64_t fElemsPerRow = tileLength_ * static_cast<int64_t>(sizeof(float)) / 32 * 32 /
                                   static_cast<int64_t>(sizeof(float));

            // Load dst half -> UB
            LocalTensor<half> dstHalf = dstReadBuf.Get<half>();
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPadExtParams<half> pp;
                pp.isPad = false;
                DataCopyPad(dstHalf, dstGm[static_cast<uint64_t>(dstOff + to)], cp, pp);
            }
            PipeBarrier<PIPE_ALL>();

            // Load src half -> UB
            LocalTensor<half> srcHalf = dataBuf.Get<half>();
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPadExtParams<half> pp;
                pp.isPad = false;
                DataCopyPad(srcHalf, srcGm[static_cast<uint64_t>(srcOff + to)], cp, pp);
            }
            PipeBarrier<PIPE_ALL>();

            // Cast to FP32 and Add
            LocalTensor<float> work = calcBuf.Get<float>();
            LocalTensor<float> dstFp32 = work;
            LocalTensor<float> srcFp32 = work[fElemsPerRow];
            Cast(dstFp32, dstHalf, RoundMode::CAST_NONE, curLen);
            Cast(srcFp32, srcHalf, RoundMode::CAST_NONE, curLen);
            Add(dstFp32, dstFp32, srcFp32, curLen);
            Cast(dstHalf, dstFp32, RoundMode::CAST_ROUND, curLen);
            PipeBarrier<PIPE_ALL>();

            // Write back
            {
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
                cp.srcStride = 0;
                cp.dstStride = 0;
                DataCopyPad(dstGm[static_cast<uint64_t>(dstOff + to)], dstHalf, cp);
            }
            PipeBarrier<PIPE_ALL>();
        }
    }
}

template <typename T>
__aicore__ inline void ScatterListKernel<T>::Process() {
    int64_t blockIdx = GetBlockIdx();
    int64_t blockNum = GetBlockNum();
    if (blockIdx >= blockNum) return;

    int64_t rowStart = blockIdx * rowsPerCore_;
    int64_t rowEnd = rowStart + rowsPerCore_;
    if (rowEnd > outerRows_) rowEnd = outerRows_;
    if (rowStart >= outerRows_) return;

    for (int64_t r = rowStart; r < rowEnd; ++r) {
        if (reduceMode_ == 0) {
            ProcessRowReplace(r);
        } else {
            ProcessRowAdd(r);
        }
    }
}

