extern "C" __global__ __aicore__ void scatter_list(
    GM_ADDR dst, GM_ADDR src,
    int64_t outerRows, int64_t srcDimSize,
    int64_t innerSize, int64_t start,
    int64_t length, int64_t dataLen,
    int64_t rowsPerCore, int64_t tileLength,
    int64_t dtypeSize, int64_t reduceMode) {

    if (dtypeSize == 4) {
        ScatterListKernel<float> op;
        op.Init(dst, src, outerRows, srcDimSize, innerSize,
                start, length, dataLen, rowsPerCore,
                tileLength, dtypeSize, reduceMode);
        op.Process();
    } else if (dtypeSize == 2) {
        ScatterListKernel<half> op;
        op.Init(dst, src, outerRows, srcDimSize, innerSize,
                start, length, dataLen, rowsPerCore,
                tileLength, dtypeSize, reduceMode);
        op.Process();
    }
}
